from ub import *
UNIT = mkunit("u131",
 ["mengenali **false friends**: kata mirip bahasa Indonesia tetapi arti berbeda",
  "memakai **actually, eventually, sensible, sympathetic, familiar, argument** dengan benar",
  "menebak arti kata dari konteks, bukan dari kemiripan",
  "menghindari salah paham dalam percakapan"],
 [intro("**False friends** adalah kata Inggris yang mirip dengan kata Indonesia (atau kata serapan) tetapi artinya berbeda. Memakainya berdasarkan kemiripan dapat membuat kalimatmu salah atau lucu. Pelajari pasangan berikut."),
  vocab("1. Kata yang menjebak", [
   ("actually", "sebenarnya (bukan 'aktual')", "Actually, I don't like coffee."), ("eventually", "akhirnya, pada akhirnya", "Eventually, we found the house."),
   ("sensible", "masuk akal / bijaksana", "That is a sensible idea."), ("sensitive", "peka / mudah tersinggung", "She is sensitive to noise."),
   ("sympathetic", "bersimpati, penuh pengertian", "He was sympathetic when I was sick."), ("nice", "menyenangkan / baik (untuk 'simpatik')", "She is a nice person."),
   ("familiar", "dikenal, tidak asing", "This song is familiar to me."), ("family", "keluarga", "My family lives in Bandung."),
   ("argument", "pertengkaran / alasan", "They had an argument."), ("current", "saat ini (bukan 'kurens')", "What is your current job?"),
   ("terrific", "hebat (bukan menakutkan)", "The show was terrific."), ("terrible", "buruk sekali", "The weather was terrible.")]),
  gram("2. Pasangan penting",
   table=[["Kata Inggris", "Arti sebenarnya", "Bukan"],
          ["**actually**", "sebenarnya / ternyata", "aktual (= current, latest)"],
          ["**eventually**", "akhirnya (setelah lama)", "eventual / kejadian"],
          ["**sensible**", "masuk akal", "sensitif (= sensitive)"],
          ["**sympathetic**", "bersimpati", "simpatik / ramah (= nice, friendly)"],
          ["**familiar**", "dikenal / akrab", "famili / keluarga (= family, relatives)"],
          ["**argument**", "pertengkaran / alasan", "argumen saja"],
          ["**terrific**", "hebat", "terrible = buruk sekali"]]),
  gram("3. Contoh dalam kalimat",
   table=[["Maksud", "Kalimat yang benar"],
          ["Berita terbaru", "[[Here is the latest news.]] (bukan *actual news*)"],
          ["Orang yang ramah", "[[He is a friendly person.]] (bukan *sympathetic person*)"],
          ["Ide masuk akal", "[[That is a sensible plan.]] (bukan *sensitive plan*)"],
          ["Akhirnya selesai", "[[Eventually, I finished the report.]]"]]),
  warn("Jangan percaya kemiripan", text="Jika kata Inggris terlihat seperti kata Indonesia, cek dulu di kamus. Kemiripan ejaan tidak menjamin arti yang sama."),
  summary(["actually = sebenarnya, bukan aktual.", "eventually = akhirnya.", "sensible = masuk akal; sensitive = peka.", "sympathetic = bersimpati; ramah = nice/friendly.", "familiar = akrab; family = keluarga.", "terrific = hebat; terrible = buruk sekali."])],
 [], [])
P = mk([
 ('Arti "actually" adalah...', 'sebenarnya', 'aktual / terbaru', 'sangat cepat', 'selalu', 'Actually = sebenarnya.'),
 ('Kata Inggris untuk "berita terbaru / aktual" adalah...', 'latest', 'actual', 'actually', 'eventual', 'Latest news.'),
 ('Arti "eventually" adalah...', 'akhirnya', 'kejadian', 'selalu', 'tiba-tiba', 'Eventually = pada akhirnya.'),
 ('Arti "sensible" adalah...', 'masuk akal', 'peka', 'sensitif terhadap kritik', 'berisik', 'Sensible = masuk akal.'),
 ('Arti "sensitive" adalah...', 'peka / mudah tersinggung', 'masuk akal', 'bijaksana', 'kuat', 'Sensitive = peka.'),
 ('Arti "sympathetic" adalah...', 'bersimpati', 'ramah dan menyenangkan', 'sombong', 'pendiam', 'Sympathetic = bersimpati.'),
 ('Kata Inggris untuk orang yang "simpatik / ramah" adalah...', 'friendly / nice', 'sympathetic', 'sensitive', 'familiar', 'Friendly person.'),
 ('Arti "familiar" adalah...', 'dikenal / tidak asing', 'keluarga', 'sangat besar', 'baru', 'Familiar = dikenal.'),
 ('Kata Inggris untuk "keluarga" adalah...', 'family', 'familiar', 'relative', 'fami', 'Family.'),
 ('Arti "argument" yang paling umum dalam percakapan adalah...', 'pertengkaran', 'ringkasan', 'pidato', 'ujian', 'Had an argument.'),
 ('Arti "current" adalah...', 'saat ini', 'arus listrik saja', 'dulu', 'nanti', 'Current job = pekerjaan saat ini.'),
 ('Arti "terrific" adalah...', 'hebat', 'menakutkan', 'buruk sekali', 'membosankan', 'Terrific = hebat.'),
 ('Arti "terrible" adalah...', 'buruk sekali', 'hebat', 'terlalu besar', 'sangat kecil', 'Terrible = sangat buruk.'),
 ('Pilih yang benar: "___, I don\'t agree with you." (sebenarnya)', 'Actually', 'Actual', 'Eventually', 'Currently', 'Actually, ...'),
 ('Pilih yang benar: "It took years, but ___ she became a doctor."', 'eventually', 'actually', 'sensibly', 'usually', 'Akhirnya.'),
 ('Pilih yang benar: "That is a very ___ idea; it will save money."', 'sensible', 'sensitive', 'sympathetic', 'familiar', 'Masuk akal.'),
 ('Pilih yang benar: "She is very ___ about her weight; do not joke about it."', 'sensitive', 'sensible', 'familiar', 'terrific', 'Peka.'),
 ('Pilih yang benar: "He was very ___ when I lost my job."', 'sympathetic', 'sensitive', 'familiar', 'terrible', 'Bersimpati.'),
 ('Pilih yang benar: "Your face looks ___. Have we met before?"', 'familiar', 'family', 'fatal', 'fabulous', 'Familiar = tidak asing.'),
 ('Pilih yang benar: "My ___ has four members."', 'family', 'familiar', 'familiarity', 'famed', 'Family = keluarga.'),
 ('Pilih yang benar: "What is your ___ address?" (alamat saat ini)', 'current', 'actual', 'actually', 'eventual', 'Current = saat ini.'),
 ('Pilih yang benar: "The concert was ___! We loved it."', 'terrific', 'terrible', 'terrify', 'terror', 'Terrific = hebat.'),
 ('Pilih yang benar: "The food was ___; nobody finished it."', 'terrible', 'terrific', 'terrifying', 'terror', 'Terrible = buruk sekali.'),
 ('Pilih kalimat yang SALAH:', 'She is a very sympathetic person, and everyone likes her smile.', 'She is a very friendly person.', 'She is very nice.', 'She was kind to me.', 'Untuk ramah, pakai friendly/nice.'),
 ('Pilih kalimat yang SALAH:', 'Here is the actual news from yesterday.', 'Here is the latest news from yesterday.', 'Here is the news.', 'Here is the current news.', 'Aktual = latest/current.'),
])
Q = mk([
 ('Arti "eventually" adalah...', 'akhirnya', 'segera', 'selalu', 'kadang-kadang', 'Eventually.'),
 ('Arti "sensible" adalah...', 'masuk akal', 'peka', 'cepat', 'mahal', 'Sensible.'),
 ('Arti "familiar" adalah...', 'dikenal', 'keluarga', 'asing', 'cepat', 'Familiar.'),
 ('Arti "actually" adalah...', 'sebenarnya', 'terbaru', 'segera', 'akhirnya', 'Actually.'),
 ('Pilih yang benar: "He is a ___ boy; everybody likes him."', 'nice', 'sympathetic', 'sensitive', 'actual', 'Nice = baik/ramah.'),
 ('Pilih yang benar: "We had a big ___ about money."', 'argument', 'argue', 'arguing', 'argues', 'Had an argument.'),
 ('Pilih kalimat yang SALAH:', 'The party was terrible; it was a great success.', 'The party was terrific.', 'The party was terrible.', 'The party was great.', 'Terrible dan great bertentangan.'),
 ('Pilih yang benar: "___, he arrived at ten." (sebenarnya, ternyata)', 'Actually', 'Eventual', 'Current', 'Sensible', 'Actually.'),
])
UNIT["practice"] = P
UNIT["quiz"] = Q
